import React, { useState, useEffect } from 'react';
import { Link } from 'react-router-dom';
import { motion } from 'framer-motion';
import { useAuth } from '../contexts/AuthContext';

interface Team {
  id: string;
  name: string;
  matchId: string;
  contestId: string;
  matchName: string;
  matchDate: string;
  captain: {
    id: string;
    name: string;
    position: string;
  };
  viceCaptain: {
    id: string;
    name: string;
    position: string;
  };
  players: Array<{
    id: string;
    name: string;
    position: string;
    points: number;
    multiplier: number;
  }>;
  totalPoints: number;
  rank: number | null;
  status: 'upcoming' | 'live' | 'completed';
  createdAt: string;
}

const MyTeamsPage: React.FC = () => {
  const { user } = useAuth();
  const [teams, setTeams] = useState<Team[]>([]);
  const [loading, setLoading] = useState(true);
  const [filter, setFilter] = useState<'all' | 'upcoming' | 'live' | 'completed'>('all');

  // Mock data for demonstration
  const mockTeams: Team[] = [
    {
      id: '1',
      name: 'Dream Warriors',
      matchId: '1',
      contestId: 'c1',
      matchName: 'Manchester United vs Liverpool',
      matchDate: '2024-03-15T15:00:00Z',
      captain: { id: 'p1', name: 'Mohamed Salah', position: 'Forward' },
      viceCaptain: { id: 'p2', name: 'Bruno Fernandes', position: 'Midfielder' },
      players: [
        { id: 'p1', name: 'Mohamed Salah', position: 'Forward', points: 25, multiplier: 2 },
        { id: 'p2', name: 'Bruno Fernandes', position: 'Midfielder', points: 18, multiplier: 1.5 },
        { id: 'p3', name: 'Virgil van Dijk', position: 'Defender', points: 12, multiplier: 1 },
        { id: 'p4', name: 'Alisson Becker', position: 'Goalkeeper', points: 8, multiplier: 1 },
        { id: 'p5', name: 'Marcus Rashford', position: 'Forward', points: 15, multiplier: 1 },
        { id: 'p6', name: 'Casemiro', position: 'Midfielder', points: 10, multiplier: 1 },
        { id: 'p7', name: 'Andrew Robertson', position: 'Defender', points: 9, multiplier: 1 },
        { id: 'p8', name: 'Jadon Sancho', position: 'Forward', points: 14, multiplier: 1 },
        { id: 'p9', name: 'Jordan Henderson', position: 'Midfielder', points: 7, multiplier: 1 },
        { id: 'p10', name: 'Harry Maguire', position: 'Defender', points: 6, multiplier: 1 },
        { id: 'p11', name: 'Sadio Mané', position: 'Forward', points: 20, multiplier: 1 }
      ],
      totalPoints: 144,
      rank: 3,
      status: 'completed',
      createdAt: '2024-03-14T10:00:00Z'
    },
    {
      id: '2',
      name: 'Victory Squad',
      matchId: '2',
      contestId: 'c2',
      matchName: 'Chelsea vs Arsenal',
      matchDate: '2024-03-15T17:30:00Z',
      captain: { id: 'p12', name: 'Bukayo Saka', position: 'Midfielder' },
      viceCaptain: { id: 'p13', name: 'Reece James', position: 'Defender' },
      players: [
        { id: 'p12', name: 'Bukayo Saka', position: 'Midfielder', points: 0, multiplier: 2 },
        { id: 'p13', name: 'Reece James', position: 'Defender', points: 0, multiplier: 1.5 },
        { id: 'p14', name: 'Mason Mount', position: 'Midfielder', points: 0, multiplier: 1 },
        { id: 'p15', name: 'Aaron Ramsdale', position: 'Goalkeeper', points: 0, multiplier: 1 },
        { id: 'p16', name: 'Gabriel Jesus', position: 'Forward', points: 0, multiplier: 1 },
        { id: 'p17', name: 'N\'Golo Kanté', position: 'Midfielder', points: 0, multiplier: 1 },
        { id: 'p18', name: 'Ben White', position: 'Defender', points: 0, multiplier: 1 },
        { id: 'p19', name: 'Raheem Sterling', position: 'Forward', points: 0, multiplier: 1 },
        { id: 'p20', name: 'Martin Ødegaard', position: 'Midfielder', points: 0, multiplier: 1 },
        { id: 'p21', name: 'Thiago Silva', position: 'Defender', points: 0, multiplier: 1 },
        { id: 'p22', name: 'Gabriel Martinelli', position: 'Forward', points: 0, multiplier: 1 }
      ],
      totalPoints: 0,
      rank: null,
      status: 'upcoming',
      createdAt: '2024-03-14T14:00:00Z'
    },
    {
      id: '3',
      name: 'Champion Eleven',
      matchId: '3',
      contestId: 'c3',
      matchName: 'Manchester City vs Tottenham',
      matchDate: '2024-03-16T14:00:00Z',
      captain: { id: 'p23', name: 'Erling Haaland', position: 'Forward' },
      viceCaptain: { id: 'p24', name: 'Kevin De Bruyne', position: 'Midfielder' },
      players: [
        { id: 'p23', name: 'Erling Haaland', position: 'Forward', points: 15, multiplier: 2 },
        { id: 'p24', name: 'Kevin De Bruyne', position: 'Midfielder', points: 12, multiplier: 1.5 },
        { id: 'p25', name: 'Ederson', position: 'Goalkeeper', points: 6, multiplier: 1 },
        { id: 'p26', name: 'Harry Kane', position: 'Forward', points: 10, multiplier: 1 },
        { id: 'p27', name: 'Son Heung-min', position: 'Forward', points: 8, multiplier: 1 },
        { id: 'p28', name: 'Rodri', position: 'Midfielder', points: 7, multiplier: 1 },
        { id: 'p29', name: 'Kyle Walker', position: 'Defender', points: 5, multiplier: 1 },
        { id: 'p30', name: 'Dejan Kulusevski', position: 'Midfielder', points: 9, multiplier: 1 },
        { id: 'p31', name: 'Pierre-Emile Højbjerg', position: 'Midfielder', points: 4, multiplier: 1 },
        { id: 'p32', name: 'Rúben Dias', position: 'Defender', points: 6, multiplier: 1 },
        { id: 'p33', name: 'Cristian Romero', position: 'Defender', points: 3, multiplier: 1 }
      ],
      totalPoints: 85,
      rank: 15,
      status: 'live',
      createdAt: '2024-03-15T12:00:00Z'
    }
  ];

  useEffect(() => {
    const fetchTeams = async () => {
      setLoading(true);
      // Simulate API call
      await new Promise(resolve => setTimeout(resolve, 1000));
      setTeams(mockTeams);
      setLoading(false);
    };

    fetchTeams();
  }, []);

  const filteredTeams = teams.filter(team => 
    filter === 'all' || team.status === filter
  );

  const getStatusBadge = (status: Team['status']) => {
    const statusConfig = {
      upcoming: { label: 'Upcoming', color: 'bg-blue-100 text-blue-800' },
      live: { label: 'Live', color: 'bg-red-100 text-red-800' },
      completed: { label: 'Completed', color: 'bg-gray-100 text-gray-800' }
    };

    const config = statusConfig[status];
    return (
      <span className={`px-2 py-1 rounded-full text-xs font-medium ${config.color}`}>
        {config.label}
        {status === 'live' && <span className="ml-1 animate-pulse">🔴</span>}
      </span>
    );
  };

  const calculateTeamValue = (players: Team['players']) => {
    return players.reduce((total, player) => total + (player.points * player.multiplier), 0);
  };

  if (loading) {
    return (
      <div className="flex items-center justify-center h-64">
        <div className="animate-spin rounded-full h-32 w-32 border-b-2 border-primary-600"></div>
      </div>
    );
  }

  return (
    <div className="space-y-6">
      {/* Header */}
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-3xl font-bold text-gray-900">My Teams</h1>
          <p className="text-gray-600 mt-1">Manage and track all your fantasy teams</p>
        </div>
        <Link to="/matches" className="btn-primary">
          Create New Team
        </Link>
      </div>

      {/* Stats Cards */}
      <div className="grid grid-cols-1 md:grid-cols-4 gap-4">
        <div className="card text-center">
          <div className="text-3xl mb-2">👥</div>
          <div className="text-2xl font-bold text-primary-600 mb-1">{teams.length}</div>
          <div className="text-sm text-gray-600">Total Teams</div>
        </div>
        <div className="card text-center">
          <div className="text-3xl mb-2">🏆</div>
          <div className="text-2xl font-bold text-green-600 mb-1">
            {teams.filter(t => t.rank && t.rank <= 3).length}
          </div>
          <div className="text-sm text-gray-600">Top 3 Finishes</div>
        </div>
        <div className="card text-center">
          <div className="text-3xl mb-2">⚽</div>
          <div className="text-2xl font-bold text-blue-600 mb-1">
            {teams.filter(t => t.status === 'live').length}
          </div>
          <div className="text-sm text-gray-600">Live Teams</div>
        </div>
        <div className="card text-center">
          <div className="text-3xl mb-2">📊</div>
          <div className="text-2xl font-bold text-purple-600 mb-1">
            {Math.round(teams.reduce((sum, t) => sum + t.totalPoints, 0) / teams.length) || 0}
          </div>
          <div className="text-sm text-gray-600">Avg Points</div>
        </div>
      </div>

      {/* Filters */}
      <div className="card">
        <div className="flex flex-wrap gap-4 items-center">
          <span className="font-medium">Filter by status:</span>
          {(['all', 'upcoming', 'live', 'completed'] as const).map((status) => (
            <button
              key={status}
              onClick={() => setFilter(status)}
              className={`px-3 py-1 rounded-full text-sm font-medium transition-colors ${
                filter === status
                  ? 'bg-primary-600 text-white'
                  : 'bg-gray-100 text-gray-600 hover:bg-gray-200'
              }`}
            >
              {status.charAt(0).toUpperCase() + status.slice(1)} ({status === 'all' ? teams.length : teams.filter(t => t.status === status).length})
            </button>
          ))}
        </div>
      </div>

      {/* Teams Grid */}
      <div className="grid gap-6">
        {filteredTeams.map((team, index) => (
          <motion.div
            key={team.id}
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            transition={{ delay: index * 0.1 }}
            className="card card-hover"
          >
            <div className="flex items-start justify-between mb-4">
              <div>
                <div className="flex items-center space-x-3 mb-2">
                  <h3 className="text-xl font-semibold text-gray-900">{team.name}</h3>
                  {getStatusBadge(team.status)}
                </div>
                <p className="text-gray-600 text-sm">{team.matchName}</p>
                <p className="text-gray-500 text-xs">
                  Created {new Date(team.createdAt).toLocaleDateString()}
                </p>
              </div>
              <div className="text-right">
                <div className="text-2xl font-bold text-primary-600">{team.totalPoints}</div>
                <div className="text-sm text-gray-600">Points</div>
                {team.rank && (
                  <div className="text-xs text-green-600 font-medium">Rank #{team.rank}</div>
                )}
              </div>
            </div>

            {/* Captain & Vice Captain */}
            <div className="grid grid-cols-2 gap-4 mb-4">
              <div className="bg-yellow-50 rounded-lg p-3">
                <div className="text-xs text-yellow-800 font-medium mb-1">CAPTAIN (2x)</div>
                <div className="font-semibold text-yellow-900">{team.captain.name}</div>
                <div className="text-xs text-yellow-700">{team.captain.position}</div>
              </div>
              <div className="bg-gray-50 rounded-lg p-3">
                <div className="text-xs text-gray-600 font-medium mb-1">VICE CAPTAIN (1.5x)</div>
                <div className="font-semibold text-gray-900">{team.viceCaptain.name}</div>
                <div className="text-xs text-gray-600">{team.viceCaptain.position}</div>
              </div>
            </div>

            {/* Team Summary */}
            <div className="grid grid-cols-4 gap-2 mb-4">
              {['Goalkeeper', 'Defender', 'Midfielder', 'Forward'].map(position => {
                const positionPlayers = team.players.filter(p => p.position === position);
                return (
                  <div key={position} className="text-center">
                    <div className="text-sm font-medium text-gray-900">
                      {positionPlayers.length}
                    </div>
                    <div className="text-xs text-gray-600">{position}s</div>
                  </div>
                );
              })}
            </div>

            {/* Actions */}
            <div className="flex space-x-3">
              <Link
                to={`/contests/${team.contestId}/leaderboard`}
                className="flex-1 btn-outline text-center text-sm"
              >
                View Contest
              </Link>
              {team.status === 'upcoming' && (
                <Link
                  to={`/contests/${team.contestId}/create-team?edit=${team.id}`}
                  className="flex-1 btn-primary text-center text-sm"
                >
                  Edit Team
                </Link>
              )}
              {team.status === 'live' && (
                <button className="flex-1 btn-outline text-center text-sm">
                  Live Tracking
                </button>
              )}
            </div>
          </motion.div>
        ))}
      </div>

      {filteredTeams.length === 0 && (
        <div className="text-center py-12">
          <div className="text-6xl mb-4">👥</div>
          <h3 className="text-xl font-semibold text-gray-900 mb-2">
            {filter === 'all' ? 'No teams found' : `No ${filter} teams`}
          </h3>
          <p className="text-gray-600 mb-4">
            {filter === 'all' 
              ? 'Create your first fantasy team to get started!' 
              : `You don't have any ${filter} teams at the moment.`
            }
          </p>
          <Link to="/matches" className="btn-primary">
            Create Your First Team
          </Link>
        </div>
      )}
    </div>
  );
};

export default MyTeamsPage;
